    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components
    components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '':
                current = ''
            elif current == '/':
                current = '/'
            else:
                # Remove last component
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
            i += 1
            continue

        # Append the component
        if current == '/':
            candidate = '/' + component
        elif current == '':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                target_current = ''
            else:
                # Relative target - relative to directory containing the link
                if candidate == '/':
                    target_current = '/'
                else:
                    last_slash = candidate.rfind('/')
                    if last_slash == 0:
                        target_current = '/'
                    else:
                        target_current = candidate[:last_slash]

            # Process target components
            target_components = target.split('/')

            # Insert remaining path components after target components
            remaining = components[i + 1:]
            components = target_components + remaining

            # Reset to process from beginning of target
            current = target_current
            i = 0
            continue

        # Not a symlink, just update current
        current = candidate
        i += 1

    # Return result without trailing slash (except for '/')
    if current == '':
        return '/'
    return current

